parameters.jsCode:
const item = $input.first().json;
const ctx = $('Validate Inbound Secret').first().json;
const allowed = new Set(
  (ctx.candidatePool || ctx.candidates_pool || [])
    .map((c) => String(c.candidateId || c.candidate_id || '').trim())
    .filter(Boolean)
);

function stripMarkdownFence(s) {
  return String(s || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
}

function hasComparePayload(obj) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  return Boolean(
    obj.comparativeSummary || obj.comparative_summary ||
    obj.candidateRanking || obj.candidate_ranking ||
    obj.decisionSummary || obj.decision_summary
  );
}

function extractLlmText(raw) {
  if (raw == null) return '';
  if (typeof raw === 'string') return raw;
  if (typeof raw !== 'object' || Array.isArray(raw)) return '';
  if (typeof raw.response === 'string' && raw.response.trim()) return raw.response;
  if (raw.response && typeof raw.response === 'object') {
    const fromResponse = extractLlmText(raw.response);
    if (fromResponse) return fromResponse;
  }
  if (typeof raw.text === 'string' && raw.text.trim()) return raw.text;
  if (typeof raw.output === 'string' && raw.output.trim()) return raw.output;
  if (raw.output && typeof raw.output === 'object') {
    const nested = extractLlmText(raw.output);
    if (nested) return nested;
  }
  if (typeof raw.message === 'string' && raw.message.trim()) return raw.message;
  if (raw.message && typeof raw.message === 'object') {
    if (typeof raw.message.content === 'string') return raw.message.content;
    if (Array.isArray(raw.message.content)) {
      return raw.message.content
        .map((part) => (typeof part === 'string' ? part : (part && part.text) || ''))
        .join('');
    }
  }
  if (Array.isArray(raw.generations) && raw.generations.length) {
    const g = raw.generations[0];
    if (typeof g === 'string') return g;
    if (g && typeof g.text === 'string') return g.text;
  }
  return '';
}

function parseLlmJson(raw) {
  if (!raw) return {};
  if (typeof raw === 'object' && !Array.isArray(raw)) {
    if (hasComparePayload(raw)) return raw;
    if (raw.output != null) {
      const fromOutput = parseLlmJson(raw.output);
      if (hasComparePayload(fromOutput)) return fromOutput;
    }
    if (raw.data != null) {
      const fromData = parseLlmJson(raw.data);
      if (hasComparePayload(fromData)) return fromData;
    }
    if (raw.response != null) {
      const fromResponse = parseLlmJson(raw.response);
      if (hasComparePayload(fromResponse)) return fromResponse;
    }
  }
  const text = stripMarkdownFence(extractLlmText(raw));
  if (!text) return {};
  try {
    const parsed = JSON.parse(text);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  } catch {
    const match = text.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        const parsed = JSON.parse(match[0]);
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
      } catch {
        return {};
      }
    }
  }
  return {};
}

function trimStr(v, max) {
  const s = v == null ? '' : String(v).trim();
  if (!s) return '';
  return s.length > max ? s.slice(0, max) : s;
}

function trimList(v, maxItems, maxLen) {
  if (!Array.isArray(v)) return undefined;
  const out = v.map((x) => trimStr(x, maxLen)).filter(Boolean).slice(0, maxItems);
  return out.length ? out : undefined;
}

function clampConf(v) {
  if (v === undefined || v === null || v === '') return undefined;
  const n = Number(v);
  if (!Number.isFinite(n)) return undefined;
  return Math.min(100, Math.max(0, Math.round(n)));
}

function normalizeInsights(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return undefined;
  const out = {};
  let count = 0;
  for (const [k, val] of Object.entries(v)) {
    if (count >= 8) break;
    const key = trimStr(k, 100);
    const value = trimStr(val, 2000);
    if (!key || !value) continue;
    out[key] = value;
    count += 1;
  }
  return count ? out : undefined;
}

const parsed = parseLlmJson(item);
const rawRanking = Array.isArray(parsed.candidateRanking)
  ? parsed.candidateRanking
  : (Array.isArray(parsed.candidate_ranking) ? parsed.candidate_ranking : []);

const candidateRanking = rawRanking.map((row, idx) => {
  const r = row && typeof row === 'object' ? row : {};
  const candidateId = String(r.candidateId || r.candidate_id || r.CandidateID || '').trim();
  const rank = Number(r.rank ?? idx + 1);
  const rec = String(r.recommendation || r.Recommendation || '').trim();
  const recommendation = rec === 'Hire' || rec === 'Consider' || rec === 'Reject' ? rec : undefined;
  return {
    rank,
    candidateId,
    candidateName: trimStr(r.candidateName || r.candidate_name || r.ApplicantName, 300),
    stageScore: r.stageScore ?? r.initial_screening_score ?? r.OverallScore ?? r.overallScore ?? '',
    competitiveAdvantage: trimStr(r.competitiveAdvantage || r.competitive_advantage, 2000),
    recommendation,
    overallRecommendation: trimStr(r.overallRecommendation || r.overall_recommendation, 300) || undefined,
    executiveComment: trimStr(r.executiveComment || r.executive_comment, 2000) || undefined,
    confidence: clampConf(r.confidence),
    confidence_rationale: trimStr(r.confidence_rationale || r.confidenceRationale, 2000) || undefined,
    reasons: trimList(r.reasons, 6, 2000),
    strengths: trimList(r.strengths, 6, 2000),
    risks: trimList(r.risks, 6, 2000),
    watchOut: trimStr(r.watchOut || r.watch_out, 2000) || undefined,
    differenceFromNext: trimStr(r.differenceFromNext || r.difference_from_next, 2000) || undefined,
    keyGaps: trimList(r.keyGaps || r.key_gaps, 4, 2000),
  };
}).filter((row) => row.candidateId && allowed.has(row.candidateId));

if (candidateRanking.length === 0) {
  throw new Error('CCMP_EMPTY_RANKING');
}

let wildcard = parsed.wildcard ?? null;
if (wildcard && typeof wildcard === 'object') {
  wildcard = {
    candidateId: String(wildcard.candidateId || '').trim(),
    candidateName: trimStr(wildcard.candidateName, 300),
    reason: trimStr(wildcard.reason, 2000),
  };
  if (!wildcard.candidateId) wildcard = null;
}

return [{
  json: {
    requestId: ctx.requestId,
    compareStage: 'stage2',
    candidateSnapshotHash: ctx.candidateSnapshotHash,
    contextualIntroduction: trimStr(parsed.contextualIntroduction || parsed.contextual_introduction, 8000),
    decisionSummary: trimStr(parsed.decisionSummary || parsed.decision_summary, 8000),
    comparativeSummary: trimStr(parsed.comparativeSummary || parsed.comparative_summary, 8000),
    comparativeInsights: normalizeInsights(parsed.comparativeInsights || parsed.comparative_insights),
    whyTopCandidateWins: trimStr(parsed.whyTopCandidateWins || parsed.why_top_candidate_wins, 8000),
    finalRecommendation: trimStr(parsed.finalRecommendation || parsed.final_recommendation, 8000),
    candidateRanking,
    topRecommendation: trimStr(parsed.topRecommendation || parsed.top_recommendation, 300),
    interviewFocus: trimStr(parsed.interviewFocus || parsed.video_interview_focus || parsed.voice_interview_focus || parsed.next_stage_focus, 4000),
    wildcard,
    callbackUrl: ctx.callbackUrl,
  },
}];

/* A short covering note. The report itself is the attached PDF — the body only
   says which job and which stage, names the leader, and points at the file. */
const body = $input.first().json.body || {};
const emails = Array.isArray(body.emails)
  ? body.emails.map((e) => String(e).trim()).filter(Boolean)
  : [];
if (emails.length === 0) throw new Error('CCMP_EMAIL_NO_RECIPIENTS');

const stage = String(body.stage || 'screening');
const stageLabel =
  stage === 'voice' ? 'المرحلة الثانية' : stage === 'video' ? 'المرحلة الثالثة' : 'المرحلة الأولى';

const ranking = Array.isArray(body.ranking) ? body.ranking : [];
const top = ranking.find((r) => Number(r.rank) === 1) || ranking[0];
const topName = String((top && top.candidateName) || (body.executiveStats && body.executiveStats.topCandidate) || '').trim();
const count = ranking.length || Number((body.executiveStats && body.executiveStats.candidateCount) || 0) || 0;

const position = String(body.position || '').trim();
const forRole = position ? ' لحملة «' + position + '»' : '';

const subject = 'تقرير مقارنة المرشحين' + (position ? ' — ' + position : '') + ' — ' + stageLabel;

const countPhrase =
  count === 0 ? '' :
  count === 1 ? 'شملت المقارنة مرشّحاً واحداً' :
  count === 2 ? 'شملت المقارنة مرشّحَين' :
  count <= 10 ? 'شملت المقارنة ' + count + ' مرشّحين' :
  'شملت المقارنة ' + count + ' مرشّحاً';

/* «المتصدّر» rather than a pronoun, so one candidate, two or ten all read correctly. */
let lead = countPhrase;
if (lead && topName) lead += count === 1 ? ': ' + topName : '، والمتصدّر: ' + topName;
else if (!lead && topName) lead = 'المتصدّر: ' + topName;

const lines = [];
lines.push('السلام عليكم ورحمة الله،');
lines.push('');
lines.push('مرفق تقرير مقارنة المرشّحين' + forRole + ' — ' + stageLabel + '.');
if (lead) lines.push(lead + '.');
lines.push('');
lines.push('التفاصيل كاملة في الملف المرفق: ترتيب المرشّحين وأسبابه، ونقاط القوّة والمخاطر لكلٍّ منهم، والتوصية النهائية.');
lines.push('');
lines.push('تقرير آلي لدعم القرار، والقرار يبقى لكم.');
lines.push('');
lines.push('مع التحية،');
lines.push('فريق evaalo');
const message = lines.join('\n');

return emails.map((email) => ({
  json: { email, subject, message, requestId: String(body.requestId || '') },
}));

const b = $('Webhook').first().json.body || {};
const pdfBase64 = typeof b.pdfBase64 === 'string' ? b.pdfBase64 : '';
const fileName = (typeof b.pdfFilename === 'string' && b.pdfFilename.trim()) ? b.pdfFilename : 'compare-report.pdf';
return $input.all().map((item) => {
  if (!pdfBase64) return item;
  return { json: item.json, binary: { ...(item.binary || {}), pdf: { data: pdfBase64, mimeType: 'application/pdf', fileName } } };
});

/* The email branch used to accept anything. Route Mode reads `mode` straight off
   the webhook and sends, while the secret check guarded only the comparison
   branch — so a plain curl with no credentials could make this mailbox send
   arbitrary text and an arbitrary PDF to any address (proven, execution 1750).
   Same secret and same constant-length comparison the other branch uses. */
const body = $input.first().json.body || {};
const expected = String($env.N8N_CAMPAIGN_COMPARE_INBOUND_SECRET || '').trim();
const received = String(body.inboundSecret ?? '').trim();

if (!expected) throw new Error('CCMP_INBOUND_SECRET_UNCONFIGURED');
if (!received || received.length !== expected.length) throw new Error('CCMP_EMAIL_SECRET_REJECTED');
if (received !== expected) throw new Error('CCMP_EMAIL_SECRET_REJECTED');

return $input.all();

/* decisionAction is the one stage-correct field the product enforces in code:
   the backend whitelists it per stage (services/compareDecisionActions.ts), so
   a Stage 2 report cannot say "hire" even if the model tries. "Build Callback
   Body" does not carry the field, and that node holds the working parser, so
   rather than edit it we add the field back here from the raw model output,
   matched on candidateId.

   Purely additive and non-fatal: on any failure the rows pass through exactly
   as they were and the comparison still completes. */
const body = $input.first().json;
const rows = Array.isArray(body.candidateRanking) ? body.candidateRanking : [];
if (rows.length === 0) return [{ json: body }];

function asText(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v !== 'object') return '';
  if (typeof v.text === 'string') return v.text;
  if (typeof v.output === 'string') return v.output;
  if (typeof v.response === 'string') return v.response;
  if (v.message && typeof v.message.content === 'string') return v.message.content;
  if (v.output && typeof v.output === 'object') return asText(v.output);
  if (v.response && typeof v.response === 'object') return asText(v.response);
  return '';
}

const actions = new Map();
try {
  const raw = $('Compare Stage 2 LLM').first().json;
  let parsed = null;
  if (raw && typeof raw === 'object' && Array.isArray(raw.candidateRanking)) {
    parsed = raw;
  } else {
    const text = asText(raw);
    const open = text.indexOf('{');
    const close = text.lastIndexOf('}');
    if (open >= 0 && close > open) parsed = JSON.parse(text.slice(open, close + 1));
  }
  const list = !parsed
    ? []
    : Array.isArray(parsed.candidateRanking)
      ? parsed.candidateRanking
      : Array.isArray(parsed.candidate_ranking)
        ? parsed.candidate_ranking
        : [];
  for (const r of list) {
    if (!r || typeof r !== 'object') continue;
    const id = String(r.candidateId || r.candidate_id || '').trim();
    const action = String(r.decisionAction || r.decision_action || '').trim();
    if (id && action && !actions.has(id)) actions.set(id, action.slice(0, 300));
  }
} catch (err) {
  console.log('[compare] decisionAction merge skipped: ' + (err && err.message));
}

if (actions.size === 0) return [{ json: body }];

return [{
  json: {
    ...body,
    candidateRanking: rows.map((row) => {
      const action = actions.get(String(row.candidateId || '').trim());
      return action ? { ...row, decisionAction: action } : row;
    }),
  },
}];
